{
  "probability": 0.96,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Late-February polls show CDU leading Greens by roughly 27–29% to 22–25%.",
    "FGW seat projection places CDU as the largest party (CDU 35 vs Greens 32).",
    "Prediction markets and multiple polls broadly support CDU finishing first, albeit Greens close the gap."
  ],
  "confidence": "high",
  "narrative": "Bayesian synthesis centers on a CDU lead in near-term polls and FGW projections, which strongly tilt the outcome toward CDU winning the most seats. While Greens momentum and historical Greens leadership inject uncertainty, the consolidated forecast yields a high posterior probability around 0.96 with a narrow uncertainty range.",
  "justification": {
    "anchor": {
      "probability": 0.96,
      "basis": "Bayesian posterior anchored in reference-class evidence: CDU leads polls (27–29%) and FGW projection (CDU largest party), consistent with ZDF/ARD snapshots."
    },
    "factor_updates": [
      {
        "factor": "CDU polling lead in February 2026 polls",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Polls consistently show CDU ahead of Greens by ~4–7 percentage points, reinforcing CDU as the largest party."
      },
      {
        "factor": "Greens closing gap in some polls",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Greens narrowing the margin reduces CDU's edge but does not overcome CDU's overall lead in multiple measures."
      },
      {
        "factor": "FGW seat projection (CDU 35 vs Greens 32)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Seat projection aligning with CDU plurality strengthens the probability of CDU winning most seats."
      },
      {
        "factor": "Historical Greens leadership in 2016 and 2021",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Past Greens-led outcomes introduce base-rate uncertainty and cap the confidence in CDU dominance."
      },
      {
        "factor": "Prediction markets and consensus CDU finishes first",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Markets and expert polls broadly favor CDU first, adding weight to a CDU-first outcome."
      },
      {
        "factor": "Electoral-system dynamics (MMP) and coalition realities",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "System effects can cushion or amplify seat shares, but do not decisively reverse the current lead."
      }
    ],
    "synthesis_rationale": "The synthesis weights CDU-lead signals more heavily (polls + FGW projection + markets). Correlated factors are acknowledged; the posterior remains high despite Greens momentum and historical precedent. Calibration adjusts for possible overconfidence due to correlated inputs and the risk of coalition effects that could affect governance even if CDU has the most seats."
  }
}

